sparql_tries.sparql:
SELECT DISTINCT ?campno WHERE {
  ?c a rc:RecallCampaign ;
     rc:doNotDrive true ;
     rc:campaignNumber ?campno ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mn .
  FILTER(UCASE(STR(?mn)) IN ("HYUNDAI","KIA","GENESIS"))
} ORDER BY ?campno

SELECT DISTINCT ?campno ?date WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campno ;
     rc:reportReceivedDate ?date ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:name "PALISADE" ;
     rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
  FILTER(?date >= "2024-01-01"^^xsd:date && ?date < "2025-01-01"^^xsd:date)
}
ORDER BY ?date

SELECT DISTINCT ?modelName ?makeName WHERE {
  ?c rc:affectsComponent ?comp .
  ?comp rc:name "SERVICE BRAKES, HYDRAULIC:ANTILOCK/TRACTION CONTROL/ELECTRONIC LIMITED SLIP:CONTROL UNIT/MODULE" .
  ?c rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:name ?modelName .
  OPTIONAL { ?m rc:ofMake ?mk . ?mk rc:name ?makeName }
} ORDER BY ?makeName ?modelName

SELECT ?compName (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c rc:affectsComponent ?comp .
  ?comp skos:broader ?parent ; rc:name ?compName .
  FILTER EXISTS { ?c1 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake/rc:name "HYUNDAI" }
  FILTER EXISTS { ?c2 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake/rc:name "KIA" }
}
GROUP BY ?compName
ORDER BY DESC(?n)
LIMIT 1

SELECT ?campaignNumber (COUNT(DISTINCT ?makeName) AS ?makeCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?makes) WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI","KIA","GENESIS"))
}
GROUP BY ?campaignNumber
HAVING (COUNT(DISTINCT ?makeName) > 1)
ORDER BY DESC(?makeCount) ?campaignNumber

SELECT DISTINCT ?campno WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campno ;
     rc:affects ?v .
  ?v rc:modelYear ?y ;
     rc:ofModel ?m .
  ?m rc:name "SANTA FE" ;
     rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
  FILTER(STR(?y) = "2021")
} ORDER BY ?campno

SELECT (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a rc:RecallCampaign ;
     rc:filedBy ?m ;
     rc:reportReceivedDate ?d .
  ?m rc:name ?mn .
  FILTER(REGEX(?mn, "HYUNDAI|KIA|GENESIS", "i"))
  FILTER(YEAR(?d) = 2023)
}

SELECT ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?r a rc:RecallCampaign ; rc:affectsComponent ?c ; rc:affects ?v .
  ?v rc:ofModel ?model .
  ?c skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?p }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?modelCount)
LIMIT 1

SELECT (COUNT(DISTINCT ?year) AS ?yearCount) WHERE {
  ?c a rc:RecallCampaign ; rc:affects ?v .
  ?v rc:ofModel ?m ; rc:modelYear ?year .
  ?m rc:name "SONATA" ; rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
}

SELECT DISTINCT ?campno WHERE {
  ?r a rc:RecallCampaign ; rc:campaignNumber ?campno .
  { ?r rc:defectSummary ?t } UNION { ?r rc:consequenceSummary ?t } UNION { ?r rc:rootCause ?t }
  FILTER(REGEX(?t, "hydrogen", "i"))
} ORDER BY ?campno

SELECT DISTINCT ?campno WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campno .
  { ?r rc:defectSummary ?t } UNION { ?r rc:rootCause ?t } UNION { ?r rc:consequenceSummary ?t }
  FILTER(REGEX(?t, "(water|moisture|liquid)", "i") && REGEX(?t, "(tow|trailer|hitch)", "i") && REGEX(?t, "(module|control unit|TCM|BCM)", "i"))
} ORDER BY ?campno
